import{_ as t,c as a,o,ae as r}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Checkout","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/checkout/index.md","filePath":"api/graphql-api/shop/checkout/index.md"}'),d={name:"api/graphql-api/shop/checkout/index.md"};function s(h,e,i,n,c,p){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="checkout" tabindex="-1">Checkout <a class="header-anchor" href="#checkout" aria-label="Permalink to &quot;Checkout&quot;">​</a></h1><p>The Checkout menu turns a prepared cart into a placed order. It runs as an ordered sequence — set the address, pick a shipping method, pick a payment method, then place the order — and provides queries to read the saved addresses and the available shipping / payment options at each step.</p><h2 id="the-checkout-sequence" tabindex="-1">The checkout sequence <a class="header-anchor" href="#the-checkout-sequence" aria-label="Permalink to &quot;The checkout sequence&quot;">​</a></h2><p>Checkout must run in order, because each step depends on the one before:</p><ol><li><strong>Set the checkout address</strong> (billing, and shipping unless the cart is virtual / downloadable only).</li><li><strong>Get shipping methods</strong> for the saved address, then <strong>set the chosen shipping method</strong>.</li><li><strong>Get payment methods</strong> available once shipping is selected, then <strong>set the chosen payment method</strong>.</li><li><strong>Place the order</strong> to finalise the cart into an order.</li></ol><p>Calling a step out of sequence (for example, fetching shipping methods before an address is saved) fails — finish the previous step first.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>Read the checkout address</td><td><a href="/api/graphql-api/shop/queries/get-addresses.html"><code>collectionGetCheckoutAddresses</code></a></td><td>The address applied to the active checkout, not the customer&#39;s address book.</td></tr><tr><td>List shipping methods</td><td><a href="/api/graphql-api/shop/queries/get-shipping-methods.html"><code>collectionShippingRates</code></a></td><td>Rates available for the saved address.</td></tr><tr><td>List payment methods</td><td><a href="/api/graphql-api/shop/queries/get-payment-methods.html"><code>collectionPaymentMethods</code></a></td><td>Methods available once shipping is chosen.</td></tr><tr><td>Set the checkout address</td><td><a href="/api/graphql-api/shop/mutations/set-billing-address.html"><code>createCheckoutAddress</code></a></td><td>Save the billing and shipping addresses on the cart.</td></tr><tr><td>Set the shipping method</td><td><a href="/api/graphql-api/shop/mutations/set-shipping-method.html"><code>createCheckoutShippingMethod</code></a></td><td>Choose one of the returned rates.</td></tr><tr><td>Set the payment method</td><td><a href="/api/graphql-api/shop/mutations/set-payment-method.html"><code>createCheckoutPaymentMethod</code></a></td><td>Choose one of the available methods.</td></tr><tr><td>Place the order</td><td><a href="/api/graphql-api/shop/mutations/place-order.html"><code>createCheckoutOrder</code></a></td><td>Convert the prepared cart into an order.</td></tr></tbody></table><p>Placing an order has two success shapes. A direct method such as cash on delivery returns the order immediately; a redirect gateway returns <code>redirect: true</code> with a <code>redirectUrl</code> and <strong>no order yet</strong> — the order is created when the gateway returns. Branch on <code>redirect</code> rather than assuming an <code>orderId</code> is present.</p><p>Checkout operates on the cart (identified by its cart token); a guest needs only the storefront key, while a signed-in customer also sends their Bearer token. See <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',10)]))}const m=t(d,[["render",s]]);export{u as __pageData,m as default};
